def calculate_n(a, b, c):
    # Expression: n = ((a+b+c)(ab+bc+ca)+a+b+c) / (4abc)
    # Simplified numerator: (a+b+c)(ab+bc+ca+1)
    numerator = (a + b + c) * (a*b + b*c + c*a + 1)
    denominator = 4 * a * b * c

    if denominator == 0:
        return None # Should not happen with positive integers

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None # Not an integer

# Search space: 1 <= a < b < c <= 20
results = []
n_equals_1_triples = []

for a in range(1, 21):
    for b in range(a + 1, 21):
        for c in range(b + 1, 21):
            n = calculate_n(a, b, c)

            if n is not None:
                results.append((a, b, c, n))
                if n == 1:
                    n_equals_1_triples.append((a, b, c))

# Output findings
print("--- All Integer Solutions Found (a < b < c <= 20) ---")
for triple, n in results:
    print(f"Triple: {triple}, n = {n}")

print("\n--- Triples where n = 1 ---")
if n_equals_1_triples:
    for triple in n_equals_1_triples:
        print(f"Triple: {triple}")
else:
    print("No triples found where n = 1 in the range.")

